public class Main {
    static final long P = 1_000_000_007L;

    // Fast power: square the base and halve the exponent, O(log e)
    static long power(long b, long e) {
        long r = 1;
        b %= P;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % P;
            b = b * b % P;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) {
        long a = 84, b = 12;
        // Fermat: b^(P-2) is the inverse of b because P is prime
        long inv = power(b, P - 2);
        // "a divided by b" becomes "a times the inverse of b"
        long q = a % P * inv % P;
        System.out.println("a=" + a + " b=" + b + " p=" + P);
        System.out.println("inverse of b = " + inv);
        System.out.println("a/b mod p = " + q);
        System.out.println("check b*inverse mod p = " + b * inv % P);
        // Time O(log p), space O(1)
    }
}

