public class Main {
    // Returns {g, x, y} with a*x + b*y = g = gcd(a, b)
    static long[] ext(long a, long b) {
        // Base case: gcd(a, 0) = a = a*1 + 0*0
        if (b == 0) return new long[]{a, 1, 0};
        // Solve the smaller problem (b, a mod b) first
        long[] r = ext(b, a % b);
        long x1 = r[1], y1 = r[2];
        // Update rule: x = y1, y = x1 - (a/b)*y1
        return new long[]{r[0], y1, x1 - (a / b) * y1};
    }

    public static void main(String[] args) {
        long a = 240, b = 46;
        long[] r = ext(a, b);
        System.out.println("a=" + a + " b=" + b);
        System.out.println("gcd=" + r[0] + " x=" + r[1] + " y=" + r[2]);
        System.out.println("check a*x + b*y = " + (a * r[1] + b * r[2]));
        // Time O(log min(a, b)), space O(log min(a, b)) for the recursion
    }
}

