using namespace std;

// Returns g = gcd(a, b) and fills x, y with a*x + b*y = g
long long ext(long long a, long long b, long long &x, long long &y) {
    // Base case: gcd(a, 0) = a = a*1 + 0*0
    if (b == 0) { x = 1; y = 0; return a; }
    long long x1, y1;
    // Solve the smaller problem (b, a mod b) first
    long long g = ext(b, a % b, x1, y1);
    // Update rule: x = y1, y = x1 - (a/b)*y1
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main() {
    long long a = 240, b = 46, x, y;
    long long g = ext(a, b, x, y);
    cout << "a=" << a << " b=" << b << endl;
    cout << "gcd=" << g << " x=" << x << " y=" << y << endl;
    cout << "check a*x + b*y = " << a * x + b * y << endl;
    // Time O(log min(a, b)), space O(log min(a, b)) for the recursion
    return 0;
}

