public class Main {
    static long power(long b, long e, long m) {
        long r = 1 % m;
        b %= m;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }

    // Extended Euclid: returns {g, x, y} with a*x + b*y = g
    static long[] ext(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] r = ext(b, a % b);
        return new long[]{r[0], r[2], r[1] - (a / b) * r[2]};
    }

    public static void main(String[] args) {
        long a = 5, m = 12; // 12 is NOT prime
        // Fermat's formula a^(m-2): only valid when m is prime
        long fermat = power(a, m - 2, m);
        // Extended Euclid works for any m, as long as gcd(a, m) = 1
        long[] r = ext(a, m);
        long euclid = (r[1] % m + m) % m; // make it non-negative
        System.out.println("a=" + a + " m=" + m);
        System.out.println("Fermat gives " + fermat + ", a*result mod m = " + a * fermat % m);
        System.out.println("Euclid gives " + euclid + ", a*result mod m = " + a * euclid % m);
        // No crash: the Fermat result is simply wrong (the product is not 1)
        // Time O(log m) for both, space O(log m) for the recursion
    }
}

