public class Main {
    // phi of one number: O(sqrt(n)) time, O(1) space
    static int phi(int n) {
        int result = n;
        for (int p = 2; p * p <= n; p++) {
            if (n % p == 0) {
                while (n % p == 0) n /= p; // strip every copy of p
                result -= result / p;      // multiply by (1 - 1/p)
            }
        }
        if (n > 1) result -= result / n;   // one prime above sqrt is left
        return result;
    }

    public static void main(String[] args) {
        System.out.println("phi(36) = " + phi(36));
        int N = 12;
        int[] ph = new int[N + 1];
        for (int i = 0; i <= N; i++) ph[i] = i;
        // Sieve: ph[p] == p means no smaller prime touched p, so p is prime
        for (int p = 2; p <= N; p++) {
            if (ph[p] == p) {
                for (int j = p; j <= N; j += p) ph[j] -= ph[j] / p;
            }
        }
        StringBuilder sb = new StringBuilder("phi(1.." + N + ") =");
        for (int i = 1; i <= N; i++) sb.append(" ").append(ph[i]);
        System.out.println(sb);
        // Sieve: O(N log log N) time, O(N) space
    }
}

