code.java:
public class Main {
    // Extended Euclid: {g, x, y} with a*x + b*y = g
    static long[] ext(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] r = ext(b, a % b);
        return new long[]{r[0], r[2], r[1] - (a / b) * r[2]};
    }

    // Merge x = a1 (mod m1) and x = a2 (mod m2); returns {x, lcm} or null
    static long[] merge(long a1, long m1, long a2, long m2) {
        long[] e = ext(m1, m2);
        long g = e[0];
        // No solution unless g divides the difference of the remainders
        if ((a2 - a1) % g != 0) return null;
        long mod = m2 / g;
        // e[1] is the inverse of m1/g modulo m2/g
        long k = ((a2 - a1) / g % mod) * (e[1] % mod) % mod;
        k = (k + mod) % mod;
        long lcm = m1 / g * m2;
        // x = a1 + m1*k, unique modulo lcm(m1, m2)
        return new long[]{(a1 + m1 * k) % lcm, lcm};
    }

    static void show(long a1, long m1, long a2, long m2) {
        long[] r = merge(a1, m1, a2, m2);
        String head = "x = " + a1 + " (mod " + m1 + "), x = " + a2 + " (mod " + m2 + ") -> ";
        if (r == null) System.out.println(head + "no solution");
        else System.out.println(head + "x = " + r[0] + " (mod " + r[1] + ")");
    }

    public static void main(String[] args) {
        show(2, 6, 8, 10);  // gcd 2 divides 8-2
        show(1, 6, 4, 10);  // gcd 2 does not divide 4-1
        show(8, 30, 3, 7);  // fold in a third congruence
        // Time O(log min(m1, m2)) per merge, space O(log) for the recursion
    }
}

