    long long mod = m2 / g;
    // x is the inverse of m1/g modulo m2/g
    long long k = ((a2 - a1) / g % mod) * (x % mod) % mod;
    k = (k + mod) % mod;
    lcm = m1 / g * m2;
    // answer = a1 + m1*k, unique modulo lcm(m1, m2)
    res = (a1 + m1 * k) % lcm;
    return true;
}

void show(long long a1, long long m1, long long a2, long long m2) {
    long long r, l;
    cout << "x = " << a1 << " (mod " << m1 << "), x = " << a2 << " (mod " << m2 << ") -> ";
    if (!merge(a1, m1, a2, m2, r, l)) cout << "no solution" << endl;
    else cout << "x = " << r << " (mod " << l << ")" << endl;
}

int main() {
    show(2, 6, 8, 10);  // gcd 2 divides 8-2
    show(1, 6, 4, 10);  // gcd 2 does not divide 4-1
    show(8, 30, 3, 7);  // fold in a third congruence
    // Time O(log min(m1, m2)) per merge, space O(log) for the recursion
    return 0;
}

