public class Main {
    static final long P = 1_000_000_007L;

    // Multiply two 2x2 matrices, reducing mod P after every product
    static long[][] mul(long[][] a, long[][] b) {
        long[][] c = new long[2][2];
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                c[i][j] = (a[i][0] * b[0][j] % P + a[i][1] * b[1][j] % P) % P;
        return c;
    }

    static long fib(long n) {
        long[][] result = {{1, 0}, {0, 1}};   // identity matrix
        long[][] base = {{1, 1}, {1, 0}};     // the step matrix T
        // Binary exponentiation: one squaring per bit of n
        while (n > 0) {
            if ((n & 1) == 1) result = mul(result, base);
            base = mul(base, base);
            n >>= 1;
        }
        // T^n = [[F(n+1), F(n)], [F(n), F(n-1)]]
        return result[0][1];
    }

    public static void main(String[] args) {
        long big = 1_000_000_000_000_000_000L;
        System.out.println("F(10) = " + fib(10));
        System.out.println("F(" + big + ") mod " + P + " = " + fib(big));
        // Time O(8 log n) = about 60 squarings, space O(1)
    }
}

