public class Main {
    static int matMuls = 0;

    static long[][] mul(long[][] a, long[][] b) {
        matMuls++; // each call costs k^3 = 27 scalar multiplications
        long[][] c = new long[3][3];
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                for (int k = 0; k < 3; k++) c[i][j] += a[i][k] * b[k][j];
        return c;
    }

    public static void main(String[] args) {
        int n = 30; // T(0)=0, T(1)=0, T(2)=1, T(n)=T(n-1)+T(n-2)+T(n-3)
        // Way 1: simple loop, one cheap step per term
        long a = 0, b = 0, c = 1;
        int steps = 0;
        for (int i = 3; i <= n; i++) {
            long d = a + b + c;
            a = b; b = c; c = d;
            steps++;
        }
        // Way 2: raise the 3x3 step matrix to the power n-2
        long[][] result = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
        long[][] base = {{1, 1, 1}, {1, 0, 0}, {0, 1, 0}};
        int e = n - 2;
        while (e > 0) {
            if ((e & 1) == 1) result = mul(result, base);
            e >>= 1;
            if (e > 0) base = mul(base, base);
        }
        System.out.println("n=" + n + " state size k=3");
        System.out.println("loop:   T(n)=" + c + " using " + steps + " loop steps");
        System.out.println("matrix: T(n)=" + result[0][0] + " using " + matMuls
                + " matrix products = " + matMuls * 27 + " scalar multiplications");
        // Loop O(n*k) time; matrix O(k^3 log n) time: it only wins for huge n
    }
}

