public class Main {
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

    public static void main(String[] args) {
        long N = 100;
        long[] d = {2, 3, 5};
        int k = d.length;
        long total = 0;
        // Every non-empty subset of the divisors is one bitmask
        for (int mask = 1; mask < (1 << k); mask++) {
            long lcm = 1;
            int bits = 0;
            for (int i = 0; i < k; i++) {
                if ((mask >> i & 1) == 1) {
                    lcm = lcm / gcd(lcm, d[i]) * d[i];
                    bits++;
                }
            }
            // N / lcm = how many numbers are divisible by all chosen divisors
            long cnt = N / lcm;
            // Odd-sized subsets are added, even-sized ones subtracted
            if (bits % 2 == 1) total += cnt; else total -= cnt;
        }
        // Brute-force check
        long brute = 0;
        for (long x = 1; x <= N; x++)
            if (x % 2 == 0 || x % 3 == 0 || x % 5 == 0) brute++;
        System.out.println("N=" + N + " divisors=2 3 5");
        System.out.println("inclusion-exclusion count = " + total);
        System.out.println("brute force count = " + brute);
        // Time O(2^k * k), space O(1); the brute force is O(N * k)
    }
}

