public class Main {
    public static void main(String[] args) {
        int n = 10;
        long[] cat = new long[n + 1];
        cat[0] = 1; // one empty object
        // First-return split: inner part of size j, outer part of size i-1-j
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i; j++)
                cat[i] += cat[j] * cat[i - 1 - j];
        StringBuilder sb = new StringBuilder("Catalan by recurrence:");
        for (int i = 0; i <= n; i++) sb.append(" ").append(cat[i]);
        System.out.println(sb);

        // Closed form: C(2n, n) / (n + 1)
        long binom = 1;
        for (int i = 0; i < n; i++) {
            // multiply first, then divide: the division is always exact
            binom = binom * (2 * n - i) / (i + 1);
        }
        System.out.println("Catalan by formula for n=" + n + ": " + binom / (n + 1));
        // Recurrence: O(n^2) time, O(n) space. Formula: O(n) time, O(1) space
    }
}

