    // Pascal's triangle mod m: works for ANY modulus, no division needed
    static int[][] pascal(int n, int m) {
        int[][] c = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            c[i][0] = 1 % m;
            for (int j = 1; j <= i; j++) c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % m;
        }
        return c;
    }

    // Lucas: split n and r into base-p digits and multiply the small binomials
    static int lucas(long n, long r, int p) {
        int[][] small = pascal(p - 1, p);
        long res = 1;
        while (n > 0 || r > 0) {
            int nd = (int) (n % p), rd = (int) (r % p);
            if (rd > nd) return 0; // a digit of r above the digit of n gives 0
            res = res * small[nd][rd] % p;
            n /= p;
            r /= p;
        }
        return (int) res;
    }

    public static void main(String[] args) {
        // Small n, composite modulus: Pascal, O(n^2) time and space
        System.out.println("Pascal: C(30,15) mod 1000 = " + pascal(30, 1000)[30][15]);
        // Huge n, small prime modulus: Lucas, O(p^2 + log n) time
        System.out.println("Lucas: C(1000000000000,123456789) mod 7 = "
                + lucas(1000000000000L, 123456789L, 7));
        // Only parity needed: C(n, r) is odd exactly when (n & r) == r, O(1)
        int n = 10, r = 3;
        System.out.println("Parity: C(10,3) is " + ((n & r) == r ? "odd" : "even"));
    }
}

