function pascal(n, m) {
  const c = [];
  for (let i = 0; i <= n; i++) {
    c.push(new Array(n + 1).fill(0));
    c[i][0] = 1 % m;
    for (let j = 1; j <= i; j++) c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % m;
  }
  return c;
}

// Lucas: split n and r into base-p digits and multiply the small binomials
function lucas(n, r, p) {
  const small = pascal(p - 1, p);
  let res = 1;
  while (n > 0 || r > 0) {
    const nd = n % p, rd = r % p;
    if (rd > nd) return 0; // a digit of r above the digit of n gives 0
    res = res * small[nd][rd] % p;
    n = Math.floor(n / p);
    r = Math.floor(r / p);
  }
  return res;
}

