public class Main {
    static long perms, fixedTotal;

    // Build every permutation of 0..n-1 and count positions where perm[i] == i
    static void build(int pos, int n, int[] perm, boolean[] used) {
        if (pos == n) {
            perms++;
            for (int i = 0; i < n; i++) if (perm[i] == i) fixedTotal++;
            return;
        }
        for (int v = 0; v < n; v++) {
            if (used[v]) continue;
            used[v] = true;
            perm[pos] = v;
            build(pos + 1, n, perm, used);
            used[v] = false; // undo the choice (backtrack)
        }
    }

    public static void main(String[] args) {
        // Theory: each position is fixed with chance 1/n, so E = n * (1/n) = 1
        for (int n = 1; n <= 6; n++) {
            perms = 0;
            fixedTotal = 0;
            build(0, n, new int[n], new boolean[n]);
            System.out.println("n=" + n + ": permutations=" + perms
                    + " fixed points in total=" + fixedTotal
                    + " average=" + fixedTotal / perms);
        }
        // Brute force costs O(n! * n) time; the formula answers in O(1)
    }
}

