public class Main {
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

    public static void main(String[] args) {
        // Game: s squares from the goal, roll a fair 3-sided die (1..3).
        // A roll that overshoots is wasted: you stay where you are (self-loop).
        int S = 6, faces = 3;
        long[] num = new long[S + 1], den = new long[S + 1];
        num[0] = 0; den[0] = 1; // already at the goal: 0 more rolls
        System.out.println("die faces=" + faces + ", overshoot = stay put");
        for (int s = 1; s <= S; s++) {
            // E[s] = 1 + (1/3) * sum of next states, where bad rolls give E[s] again.
            // Move the E[s] terms left: E[s] = (3 + sum of E[s-d] for valid d) / valid
            long sn = faces, sd = 1;
            int valid = 0;
            for (int d = 1; d <= faces && d <= s; d++) {
                sn = sn * den[s - d] + num[s - d] * sd; // add the fraction E[s-d]
                sd = sd * den[s - d];
                valid++;
            }
            sd *= valid;
            long g = gcd(sn, sd); // keep the fraction reduced
            num[s] = sn / g;
            den[s] = sd / g;
            System.out.println("E[" + s + "] = " + num[s] + "/" + den[s]);
        }
        // Time O(S * faces), space O(S)
    }
}

