public class Main {
    public static void main(String[] args) {
        int[] moves = {1, 3, 4};
        int[] piles = {5, 7, 9};
        int max = 9;
        int[] g = new int[max + 1]; // g[0] = 0: no move, a losing position
        for (int x = 1; x <= max; x++) {
            // Mark the Grundy numbers of every position reachable from x
            boolean[] seen = new boolean[moves.length + 2];
            for (int s : moves) if (s <= x) seen[g[x - s]] = true;
            // mex = smallest non-negative number that is not reachable
            int m = 0;
            while (seen[m]) m++;
            g[x] = m;
        }
        StringBuilder sb = new StringBuilder("grundy 0.." + max + " =");
        for (int x = 0; x <= max; x++) sb.append(" ").append(g[x]);
        // Independent piles combine with XOR
        int xr = 0;
        for (int p : piles) xr ^= g[p];
        System.out.println("moves=1 3 4 piles=5 7 9");
        System.out.println(sb);
        System.out.println("xor of pile grundy numbers = " + xr);
        System.out.println(xr != 0 ? "First player wins" : "Second player wins");
        // Time O(max * |moves| + piles), space O(max)
    }
}

