public class Main {
    static void report(int[] heaps) {
        // XOR all heap sizes together
        int x = 0;
        StringBuilder sb = new StringBuilder("heaps =");
        for (int h : heaps) { x ^= h; sb.append(" ").append(h); }
        System.out.println(sb + ", xor = " + x);
        if (x == 0) {
            // Every move changes one heap, so the XOR must become non-zero
            System.out.println("  xor is 0: the first player loses");
            return;
        }
        for (int i = 0; i < heaps.length; i++) {
            // A heap that has the top bit of x gets smaller when XORed with x
            int target = heaps[i] ^ x;
            if (target < heaps[i]) {
                System.out.println("  first player wins: reduce heap " + i
                        + " from " + heaps[i] + " to " + target);
                heaps[i] = target;
                break;
            }
        }
        int check = 0;
        for (int h : heaps) check ^= h;
        System.out.println("  xor after the move = " + check);
    }

    public static void main(String[] args) {
        report(new int[]{3, 4, 5});
        report(new int[]{1, 2, 3});
        // Time O(n), space O(1)
    }
}

