using System;
using System.Text;

class Program {
    static void Report(int[] heaps) {
        // XOR all heap sizes together
        int x = 0;
        StringBuilder sb = new StringBuilder("heaps =");
        foreach (int h in heaps) { x ^= h; sb.Append(" ").Append(h); }
        Console.WriteLine(sb.ToString() + ", xor = " + x);
        if (x == 0) {
            // Every move changes one heap, so the XOR must become non-zero
            Console.WriteLine("  xor is 0: the first player loses");
            return;
        }
        for (int i = 0; i < heaps.Length; i++) {
            // A heap that has the top bit of x gets smaller when XORed with x
            int target = heaps[i] ^ x;
            if (target < heaps[i]) {
                Console.WriteLine("  first player wins: reduce heap " + i
                    + " from " + heaps[i] + " to " + target);
                heaps[i] = target;
                break;
            }
        }
        int check = 0;
        foreach (int h in heaps) check ^= h;
        Console.WriteLine("  xor after the move = " + check);
    }

    static void Main() {
        Report(new int[] { 3, 4, 5 });
        Report(new int[] { 1, 2, 3 });
        // Time O(n), space O(1)
    }
}
